import {sceneName,filterLines,tokenize,lookupDictionary,labels,advanceProgress,plain,grammarDescription} from './data.js';
import {icon,esc,el,button,openSheet,isSheetOpen,toast,closeSheet,syncSelects} from './ui.js';
export function directionText(d){return typeof d==='string'?d:plain(d?.ja);}
export function showDirection(line){const d=line.direction;openSheet('ト書き',`<p>${esc(directionText(d)||'日本語要約は未収録です。')}</p>${typeof d==='object'&&d.original?`<div class="sheet-section"><h3>原文</h3><p lang="en">${esc(d.original)}</p><p class="subtle">出典: ${esc(d.source||'読み込みデータ')}</p></div>`:''}`);}
export function showDictionary(line,token,ctx){const d=lookupDictionary(ctx.data.dictionary,token),v=token.entry;
 openSheet(v?.lemma||d?.lemma||token.text,`<div class="dictionary-word" lang="en">${esc(v?.lemma||d?.lemma||token.text)}</div><div class="dictionary-meta">${esc(d?.pos||'品詞未収録')} ${esc(d?.ipa||'')}</div>${d||v?`<p class="meaning">${esc(d?.coreMeaning||v?.meaning||d?.contextMeaning)}</p><div class="sheet-section"><h3>このセリフでは</h3><p>${esc(v?.meaning||d.contextMeaning||'個別の語釈は未収録です。')}</p>${d?.contextExplanation?`<p class="subtle" style="margin-top:10px">${esc(d.contextExplanation)}</p>`:''}</div>${d?.pattern||d?.forms?`<div class="sheet-section"><h3>語法・表現</h3>${d.pattern?`<p lang="en"><strong>${esc(d.pattern)}</strong></p>`:''}<p>${esc(d.patternDesc||d.forms)}</p></div>`:''}`:`<p>この単語の辞書データは未収録です。</p><p class="subtle" style="margin-top:12px">セリフの解説で、日本語訳や登録済みの表現を確認できます。</p>`}<div class="sheet-section"><h3>セリフ</h3><p lang="en" class="analysis-quote">${esc(line.text)}</p>${button('セリフの解説を見る','analyze-word','secondary')}</div>`,{setup:sheet=>{sheet.querySelector('[data-action=analyze-word]').onclick=()=>showAnalysis(line,ctx);}});
}
// The provided JSON contains translations, not a per-line intent/acting essay.
// Resolve adjacent lines in the same scene without inferring dramatic intent.
export function analysisNeighbor(data,line,delta){
 const neighbor=data.lines[line.index+delta];
 if(!neighbor||neighbor.scene!==line.scene)return null;
 const entry=data.translations[neighbor.id];
 const translation=typeof entry==='string'?entry:entry?.translation;
 return {speaker:neighbor.speaker,translation:plain(translation),text:neighbor.text};
}
export function showAnalysis(line,ctx){const {data,progress,small,setProgress,save}=ctx,t=data.translations[line.id],translation=typeof t==='string'?t:t?.translation,grammar=data.grammar[line.id]||[],vocab=data.vocabulary[line.id]||[],p=progress[line.id]||{},note=small.notes?.[line.id]||{},previous=analysisNeighbor(data,line,-1),following=analysisNeighbor(data,line,1),neighbors=[['直前',previous],['直後',following]].filter(([,item])=>item).map(([label,item])=>`<div class="analysis-neighbor"><span class="analysis-neighbor-label">${esc(label)} · ${esc(item.speaker)}</span><p>${esc(item.translation||item.text)}</p></div>`).join('');
 openSheet(`${line.speaker} · セリフ ${line.ordinal}`,`<p lang="en" class="analysis-quote">${esc(line.text)}</p><h3 class="eyebrow" style="margin-bottom:10px">日本語訳</h3><p>${esc(translation||'日本語訳は未収録です。')}</p><div class="sheet-section analysis-context"><h3>会話の流れ・文脈</h3>${line.context?`<p class="analysis-intent">${esc(line.context)}</p>`:''}<p class="subtle">前後の発話を、提供済みの日本語訳から表示しています。</p>${neighbors||'<p class="subtle">この場面に隣接するセリフはありません。</p>'}<details class="analysis-personal"><summary>自分の解釈を記録</summary><label class="form-stack" style="margin-top:12px;font-size:12px">セリフの意図<input id="context-note" placeholder="相手に何を伝えたい？" value="${esc(note.context||'')}" maxlength="2000"></label></details></div><div class="sheet-section analysis-acting"><h3>演技のポイント</h3>${line.acting?`<p>${esc(line.acting)}</p>`:directionText(line.direction)?`<p class="analysis-stage-cue">${esc(directionText(line.direction))}</p><p class="subtle">対応が確認できたト書きの日本語要約です。</p>`:'<p class="subtle">このセリフに対応付けられた演技指示はありません。</p>'}<details class="analysis-personal"><summary>演技メモを記録</summary><label class="form-stack" style="margin-top:12px;font-size:12px">演技メモ<input id="acting-note" placeholder="間の取り方・視線・強調する語など" value="${esc(note.acting||'')}" maxlength="2000"></label></details>${line.direction&&typeof line.direction==='object'&&line.direction.original?`<details class="analysis-stage-original"><summary>元のト書きと出典</summary><p lang="en">${esc(line.direction.original)}</p><p class="subtle">${esc(line.direction.source||'提供データ')}</p></details>`:''}</div><div class="sheet-section"><h3>文法・構文</h3>${grammar.length?grammar.map(g=>`<div class="grammar-item"><strong>${esc(g.pattern)}</strong><p>${esc(grammarDescription(g).text)}</p></div>`).join(''):'<p class="subtle">このセリフの文法解説はまだありません。</p>'}</div><div class="sheet-section"><h3>重要表現</h3>${vocab.length?vocab.map((v,i)=>`<button class="scene-link" data-vocab="${i}"><span class="scene-link-text"><strong lang="en">${esc(v.surface)}</strong><small>${esc(v.meaning)}</small></span>${icon('chevron')}</button>`).join(''):'<p class="subtle">登録された重要表現はありません。</p>'}</div><div class="sheet-section"><h3>学習状態</h3><div class="button-row">${button(labels[p.level||0],'level-analysis','secondary','check')}${button(p.review?'要復習を解除':'要復習に追加','review-analysis','secondary','flag')}</div></div>`,{setup:sheet=>{
 const level=sheet.querySelector('[data-action=level-analysis]'),review=sheet.querySelector('[data-action=review-analysis]');
 level.onclick=()=>{setProgress(line.id,advanceProgress(progress[line.id]));level.querySelector('span').textContent=labels[progress[line.id].level];};review.onclick=()=>{setProgress(line.id,{...progress[line.id],review:!progress[line.id]?.review,updatedAt:Date.now()});review.querySelector('span').textContent=progress[line.id].review?'要復習を解除':'要復習に追加';};
 sheet.querySelectorAll('[data-vocab]').forEach(b=>b.onclick=()=>showDictionary(line,{text:vocab[b.dataset.vocab].surface,entry:vocab[b.dataset.vocab]},ctx));
 const storeNote=()=>{small.notes||={};small.notes[line.id]={context:sheet.querySelector('#context-note').value,acting:sheet.querySelector('#acting-note').value};save();};sheet.querySelector('#context-note').oninput=storeNote;sheet.querySelector('#acting-note').oninput=storeNote;
 }});
}
export function speechNode(line,ctx,{words=true}={}){const p=ctx.progress[line.id]||{};const node=el(`<article class="speech ${line.speaker===ctx.small.role?'mine':''}" id="line-${esc(line.id)}" data-id="${esc(line.id)}" tabindex="0" aria-label="${esc(line.speaker)}、セリフ ${line.ordinal}。Enterで文の解析"><div class="swipe-hint"></div><div class="speech-inner"><div class="speech-head"><span class="speaker">${esc(line.speaker)}</span><div class="speech-actions"><span class="speech-status" role="img" data-level="${p.level||0}" aria-label="${labels[p.level||0]}${p.review?'・要復習':''}" ${!p.level&&!p.review?'hidden':''}><i class="level-state"></i><span class="review-state" ${p.review?'':'hidden'}>${icon('flag')}</span></span><button type="button" class="speech-bookmark" data-action="bookmark" aria-label="${p.bookmarked?'栞を外す':'栞を付ける'}" aria-pressed="${!!p.bookmarked}" title="栞">${icon('bookmark')}</button></div></div>${directionText(line.direction)?`<button class="direction" data-action="direction" aria-label="ト書きの詳細">${esc(directionText(line.direction))}</button>`:''}<p class="speech-text" lang="en">${esc(line.text)}</p></div></article>`);
 node.querySelector('[data-action=bookmark]').onclick=()=>{const current=ctx.progress[line.id]||{};ctx.setProgress(line.id,{...current,bookmarked:!current.bookmarked,updatedAt:Date.now()});};node.querySelector('[data-action=direction]')?.addEventListener('click',()=>showDirection(line));
 let suppressed=false;
 node.addEventListener('click',e=>{if(suppressed){e.preventDefault();e.stopImmediatePropagation();}else if(!e.target.closest('button,a,input,select,textarea,[contenteditable]')&&!window.getSelection()?.toString())showAnalysis(line,ctx);},true);
 node.addEventListener('keydown',e=>{if(e.target===node&&(e.key==='Enter'||e.key===' ')){e.preventDefault();showAnalysis(line,ctx);}});
 node.renderWords=()=>{if(node.dataset.tokenized||!words)return;node.dataset.tokenized='1';const paragraph=node.querySelector('.speech-text');paragraph.replaceChildren();for(const token of tokenize(line.text,ctx.data.vocabulary[line.id]||[])){const d=(token.word||token.entry)&&lookupDictionary(ctx.data.dictionary,token),hasMeaning=plain(token.entry?.meaning).trim()||plain(d?.coreMeaning).trim()||plain(d?.contextMeaning).trim();if(hasMeaning){const b=document.createElement('button');b.type='button';b.className='word'+(token.entry?' phrase':'');b.textContent=token.text;b.setAttribute('aria-label',`${token.text} の意味`);b.onclick=()=>showDictionary(line,token,ctx);paragraph.append(b);}else paragraph.append(document.createTextNode(token.text));}};
 let gesture;
 node.addEventListener('pointerdown',e=>{if(e.button!==0||e.target.closest('button:not(.word)'))return;gesture={x:e.clientX,y:e.clientY,id:e.pointerId,dx:0,locked:false};},{passive:true});
 node.addEventListener('pointermove',e=>{if(!gesture||e.pointerId!==gesture.id)return;const dx=e.clientX-gesture.x,dy=e.clientY-gesture.y;if(!gesture.locked){if(Math.abs(dy)>10&&Math.abs(dy)>Math.abs(dx)){gesture=null;return;}if(Math.abs(dx)>12&&Math.abs(dx)>Math.abs(dy)*1.5){gesture.locked=true;node.setPointerCapture(e.pointerId);}else return;}gesture.dx=dx;const hint=node.querySelector('.swipe-hint');hint.style.opacity=Math.min(1,Math.abs(dx)/70);hint.textContent=dx>0?`→ ${labels[((ctx.progress[line.id]?.level||0)+1)%3]}`:'要復習を切り替え ←';hint.classList.toggle('left',dx<0);node.querySelector('.speech-inner').style.transform=`translateX(${Math.max(-100,Math.min(100,dx*.65))}px)`;});
 const reset=()=>{node.querySelector('.swipe-hint').style.opacity=0;node.querySelector('.speech-inner').style.transform='';};
 node.addEventListener('pointerup',e=>{if(!gesture||gesture.id!==e.pointerId)return;const g=gesture;gesture=null;if(g.locked){suppressed=true;setTimeout(()=>suppressed=false,300);if(Math.abs(g.dx)>68){if(g.dx>0)ctx.setProgress(line.id,advanceProgress(ctx.progress[line.id]));else ctx.setProgress(line.id,{...ctx.progress[line.id],review:!ctx.progress[line.id]?.review,updatedAt:Date.now()});}}reset();});node.addEventListener('pointercancel',()=>{gesture=null;reset();});
 return node;
}
export function updateSpeech(node,p={}){
 const status=node.querySelector('.speech-status');if(!status)return;
 status.dataset.level=p.level||0;status.hidden=!p.level&&!p.review;status.setAttribute('aria-label',`${labels[p.level||0]}${p.review?'・要復習':''}`);status.querySelector('.review-state').hidden=!p.review;
 const bookmark=node.querySelector('[data-action=bookmark]');if(bookmark){bookmark.setAttribute('aria-pressed',String(!!p.bookmarked));bookmark.setAttribute('aria-label',p.bookmarked?'栞を外す':'栞を付ける');}
}
export function mountReader(main,ctx){const {data,small,save,progress}=ctx;let destroyStick=()=>{},observer,scrollFrame,saveTimer,disposed=false;const visible=new Set();let lines=[],lastJump=null;
 const root=el(`<div class="reader-top"><div class="reader-heading"><h1>台本</h1><span class="reader-count"></span></div><div class="reader-tools"><button class="reader-role" data-action="role" aria-label="担当する役を変更。現在: ${esc(small.role)}">${esc(small.role)} ${icon('down')}</button><button class="icon-button" data-action="search" aria-label="検索と絞り込み" aria-expanded="false">${icon('search')}</button><button class="icon-button" data-action="scene" aria-label="場面を選ぶ">${icon('book')}</button></div></div>`);main.append(root);
 root.querySelector('[data-action=role]').onclick=ctx.openRolePicker;
 const filters=el(`<div class="reader-filter hide"><label class="search-field">セリフを検索<input type="search" placeholder="英文・日本語訳・役名" value="${esc(small.query||'')}" aria-label="セリフを検索"></label><label>役<select id="speaker-filter"><option value="all">すべての役</option>${ctx.roles().map(s=>`<option value="${esc(s)}">${esc(s)}</option>`).join('')}</select></label><label>表示<select id="review-filter"><option value="all">すべて</option><option value="review">要復習のみ</option><option value="bookmarked">栞を付けたセリフ</option></select></label><button class="text-button" data-action="clear-filters">条件をクリア</button></div>`);main.append(filters);
 const scroller=el('<div class="page-scroll reader-scroll" tabindex="0" aria-label="台本本文"></div>'),body=el('<div class="script-body"></div>');scroller.append(body);main.append(scroller);body.style.setProperty('--font',small.font+'px');body.style.setProperty('--reader-leading',small.leading);
 filters.querySelector('#speaker-filter').value=small.speaker||'all';filters.querySelector('#review-filter').value=small.bookmarkOnly?'bookmarked':small.reviewOnly?'review':'all';
 const nodeById=new Map();
 function current(anchor=55){let best=null,dist=Infinity;const top=scroller.getBoundingClientRect().top,point=top+anchor;for(const n of visible){const r=n.getBoundingClientRect();if(r.bottom<top)continue;if(r.top<=point&&r.bottom>point)return n;const d=Math.abs(r.top-point);if(d<dist){best=n;dist=d;}}return best;}
 function remember(){const n=current();if(n){small.read={id:n.dataset.id,offset:n.getBoundingClientRect().top-scroller.getBoundingClientRect().top,scene:small.scene};save();}}
 function jump(id,highlight=true,offset=null){const n=nodeById.get(id);if(!n){toast('この表示範囲に対象のセリフがありません');return;}lastJump=id;n.renderWords();n.style.contentVisibility='visible';const align=()=>{if(disposed)return;const r=n.getBoundingClientRect(),viewport=scroller.getBoundingClientRect();const target=offset===null?Math.max(24,(scroller.clientHeight-r.height)/2):offset;scroller.scrollTop+=r.top-viewport.top-target;};align();requestAnimationFrame(()=>requestAnimationFrame(align));if(highlight){n.classList.add('highlight');setTimeout(()=>{n.classList.remove('highlight');n.style.contentVisibility='';},1600);}}
 function jumpMine(direction){if(isSheetOpen())return;const currentNode=current(scroller.clientHeight/2),index=lines.findIndex(l=>l.id===(lastJump||currentNode?.dataset.id)),target=direction>0?lines.find((l,i)=>i>index&&l.speaker===small.role):lines.slice(0,Math.max(0,index)).reverse().find(l=>l.speaker===small.role);if(target)jump(target.id);else toast(direction>0?'次の自分のセリフはありません':'前の自分のセリフはありません');}
 async function draw(restore=false){const started=performance.now();observer?.disconnect();lastJump=null;visible.clear();nodeById.clear();body.replaceChildren();lines=filterLines(data,{scene:small.scene,speaker:small.speaker||'all',query:small.query||'',reviewOnly:small.reviewOnly,bookmarkedOnly:small.bookmarkOnly,progress});root.querySelector('.reader-count').textContent=`${lines.length}件のセリフ`;
 if(!lines.length){body.innerHTML='<div class="empty"><h2>該当するセリフがありません</h2><p>場面や検索・絞り込み条件を変更してください。</p></div>';return;}
 observer=new IntersectionObserver(entries=>{for(const e of entries){if(e.isIntersecting){visible.add(e.target);e.target.renderWords();}else visible.delete(e.target);}},{root:scroller,rootMargin:'200px 0px'});
 let scene='';const frag=document.createDocumentFragment();for(const line of lines){if(line.scene!==scene){scene=line.scene;frag.append(el(`<div class="scene-divider"><h2>${esc(sceneName(scene))}</h2></div>`));}const n=speechNode(line,ctx);nodeById.set(line.id,n);frag.append(n);}body.append(frag);for(const n of nodeById.values())observer.observe(n);body.dataset.renderMs=(performance.now()-started).toFixed(1);
 if(restore&&small.read.id&&nodeById.has(small.read.id))jump(small.read.id,false,small.read.offset??40);else scroller.scrollTop=0;
 }
 const change=()=>{small.query=filters.querySelector('input').value;small.speaker=filters.querySelector('#speaker-filter').value;small.reviewOnly=filters.querySelector('#review-filter').value==='review';small.bookmarkOnly=filters.querySelector('#review-filter').value==='bookmarked';save();draw();};let queryTimer;
 filters.querySelector('input').oninput=()=>{clearTimeout(queryTimer);queryTimer=setTimeout(change,160);};filters.querySelectorAll('select').forEach(s=>s.onchange=change);filters.querySelector('[data-action=clear-filters]').onclick=()=>{filters.querySelector('input').value='';filters.querySelector('#speaker-filter').value='all';filters.querySelector('#review-filter').value='all';syncSelects(filters);change();};
 root.querySelector('[data-action=search]').onclick=e=>{filters.classList.toggle('hide');e.currentTarget.setAttribute('aria-expanded',!filters.classList.contains('hide'));if(!filters.classList.contains('hide'))filters.querySelector('input').focus();};
 root.querySelector('[data-action=scene]').onclick=()=>openSheet('場面を選ぶ',`<div class="reader-shortcuts"><button class="secondary" data-jump="-1">前の自分のセリフ</button><button class="secondary" data-jump="1">次の自分のセリフ</button></div><button class="scene-link" data-scene="all"><strong>すべての場面を表示</strong></button>${data.scenes.map(s=>`<button class="scene-link" data-scene="${esc(s.id)}"><span class="scene-link-text"><strong>${esc(s.title)}</strong><small>${s.lines.length}件のセリフ</small></span>${icon('chevron')}</button>`).join('')}`,{setup:sheet=>{sheet.querySelectorAll('[data-jump]').forEach(b=>b.onclick=()=>{closeSheet();jumpMine(+b.dataset.jump);});sheet.querySelectorAll('[data-scene]').forEach(b=>b.onclick=()=>{remember();small.scene=b.dataset.scene;small.read={};save();closeSheet();draw();});}});

 scroller.addEventListener('scroll',()=>{if(scrollFrame)return;scrollFrame=requestAnimationFrame(()=>{scrollFrame=0;clearTimeout(saveTimer);saveTimer=setTimeout(remember,180);});},{passive:true});
 const onProgress=e=>{const n=nodeById.get(e.detail);if(!n)return;if((small.bookmarkOnly&&!progress[e.detail]?.bookmarked)||(small.reviewOnly&&!progress[e.detail]?.review)){const top=scroller.scrollTop;void draw().then(()=>{if(!disposed)scroller.scrollTop=top;});return;}updateSpeech(n,progress[e.detail]);};window.addEventListener('progresschange',onProgress);
 scroller.addEventListener('pointerdown',()=>{lastJump=null;},{passive:true});scroller.addEventListener('wheel',()=>{lastJump=null;},{passive:true});scroller.addEventListener('keydown',()=>{lastJump=null;});draw(true);if(small.stick)import('./stick.js').then(({mountStick})=>{if(!disposed)destroyStick=mountStick(main.closest('.main-shell'),scroller,jumpMine,()=>{lastJump=null;});});
 const onHide=()=>{if(document.hidden)remember();};document.addEventListener('visibilitychange',onHide);window.addEventListener('pagehide',remember);
 return ()=>{remember();disposed=true;destroyStick();observer?.disconnect();clearTimeout(saveTimer);clearTimeout(queryTimer);cancelAnimationFrame(scrollFrame);window.removeEventListener('progresschange',onProgress);document.removeEventListener('visibilitychange',onHide);window.removeEventListener('pagehide',remember);};
}
